#endif
layout(std140) uniform f_buffer0 {
	vec4 f_cb0[22];
} _f_buffer0;
uniform highp sampler2D f_t0TEX_with_SMPf_s2;
uniform highp sampler2D f_t0;
uniform highp sampler2D f_t1TEX_with_SMPf_s5;
uniform highp sampler2D f_t1;
uniform highp sampler2D f_t2TEX_with_SMPf_s4;
uniform highp sampler2D f_t2;
uniform highp sampler2D f_t3TEX_with_SMPf_s3;
uniform highp sampler2D f_t3;
uniform highp sampler2D f_t4TEX_with_SMPf_s0;
uniform highp sampler2D f_t4;
uniform highp sampler2D f_t5TEX_with_SMPf_s6;
uniform highp sampler2D f_t5;
uniform highp sampler2D f_t6TEX_with_SMPf_s1;
uniform highp sampler2D f_t6;
in highp vec2 vs_TEXCOORD0;
in highp vec2 vs_TEXCOORD1;
in highp vec2 vs_TEXCOORD2;
in highp vec2 vs_TEXCOORD4;
in highp vec4 vs_TEXCOORD3;
in highp vec2 vs_TEXCOORD5;
in highp vec2 vs_TEXCOORD6;
in highp vec4 vs_COLOR0;
layout(location = 0) out highp vec4 SV_Target0;
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
vec4 u_xlat3;
vec3 u_xlat4;
vec3 u_xlat5;
vec3 u_xlat7;
float u_xlat15;
void main()
{
    u_xlat0 = texture(f_t2TEX_with_SMPf_s4, vs_TEXCOORD4.xy);
    u_xlat0.xyz = (-u_xlat0.xyz) + _f_buffer0.f_cb0[8].yyy;
    u_xlat5.xyz = abs(u_xlat0.xyz) * _f_buffer0.f_cb0[7].xyz;
    u_xlat0.x = abs(u_xlat0.x) + -0.5;
    u_xlat5.xyz = u_xlat5.xyz * _f_buffer0.f_cb0[7].www;
    u_xlat0.yzw = u_xlat5.xyz * _f_buffer0.f_cb0[8].xxx;
    u_xlat1 = texture(f_t0TEX_with_SMPf_s2, vs_TEXCOORD0.xy);
    u_xlat0 = u_xlat0 * u_xlat1.yyyy;
    u_xlat5.xyz = u_xlat0.yzw * vs_TEXCOORD3.yyy;
    u_xlat2 = texture(f_t3TEX_with_SMPf_s3, vs_TEXCOORD2.xy);
    u_xlat2.xyz = (-u_xlat2.xyz) + _f_buffer0.f_cb0[4].yyy;
    u_xlat7.xyz = abs(u_xlat2.xyz) * _f_buffer0.f_cb0[3].xyz;
    u_xlat2.x = abs(u_xlat2.x) + -0.5;
    u_xlat7.xyz = u_xlat7.xyz * _f_buffer0.f_cb0[3].www;
    u_xlat2.yzw = u_xlat7.xyz * _f_buffer0.f_cb0[4].xxx;
    u_xlat2 = u_xlat1.xxxx * u_xlat2;
    u_xlat3.xyz = u_xlat2.yzw * vs_TEXCOORD3.xxx + u_xlat5.xyz;
    u_xlat7.xyz = u_xlat2.yzw * vs_TEXCOORD3.xxx;
    u_xlat3.xyz = u_xlat3.xyz * vec3(0.5, 0.5, 0.5);
    u_xlat5.xyz = u_xlat7.xyz * u_xlat5.xyz + (-u_xlat3.xyz);
    u_xlat5.xyz = _f_buffer0.f_cb0[8].zzz * u_xlat5.xyz + u_xlat3.xyz;
    u_xlat3 = texture(f_t1TEX_with_SMPf_s5, vs_TEXCOORD5.xy);
    u_xlat7.xyz = (-u_xlat3.xyz) + _f_buffer0.f_cb0[13].zzz;
    u_xlat3.xyz = abs(u_xlat7.xyz) * _f_buffer0.f_cb0[12].xyz;
    u_xlat7.x = abs(u_xlat7.x) + -0.5;
    u_xlat7.x = u_xlat1.z * u_xlat7.x;
    u_xlat3.xyz = u_xlat3.xyz * _f_buffer0.f_cb0[12].www;
    u_xlat3.xyz = u_xlat3.xyz * _f_buffer0.f_cb0[13].xxx;
    u_xlat3.xyz = u_xlat1.zzz * u_xlat3.xyz;
    u_xlat4.xyz = u_xlat3.xyz * vs_TEXCOORD3.zzz + u_xlat5.xyz;
    u_xlat3.xyz = u_xlat3.xyz * vs_TEXCOORD3.zzz;
    u_xlat4.xyz = u_xlat4.xyz * vec3(0.5, 0.5, 0.5);
    u_xlat5.xyz = u_xlat5.xyz * u_xlat3.xyz + (-u_xlat4.xyz);
    u_xlat5.xyz = _f_buffer0.f_cb0[13].www * u_xlat5.xyz + u_xlat4.xyz;
    u_xlat0.x = u_xlat0.x * _f_buffer0.f_cb0[8].w;
    u_xlat0.x = u_xlat7.x * _f_buffer0.f_cb0[14].x + u_xlat0.x;
    u_xlat0.x = u_xlat2.x * _f_buffer0.f_cb0[4].z + u_xlat0.x;
    u_xlat2.xy = _f_buffer0.f_cb0[21].zw * u_xlat0.xx + vs_TEXCOORD0.xy;
    u_xlat2 = texture(f_t4TEX_with_SMPf_s0, u_xlat2.xy);
    u_xlat0.xyz = u_xlat5.xyz + u_xlat2.xyz;
    u_xlat0.xyz = _f_buffer0.f_cb0[20].www * _f_buffer0.f_cb0[21].xxx + u_xlat0.xyz;
    u_xlat0.xyz = (-u_xlat2.xyz) + u_xlat0.xyz;
    u_xlat15 = u_xlat1.y + u_xlat1.x;
    u_xlat15 = u_xlat1.z + u_xlat15;
#ifdef UNITY_ADRENO_ES3
    u_xlat15 = min(max(u_xlat15, 0.0), 1.0);
#else
    u_xlat15 = clamp(u_xlat15, 0.0, 1.0);
#endif
    u_xlat0.xyz = vec3(u_xlat15) * u_xlat0.xyz + u_xlat2.xyz;
    u_xlat2 = texture(f_t5TEX_with_SMPf_s6, vs_TEXCOORD6.xy);
    u_xlat2 = u_xlat2 * _f_buffer0.f_cb0[17];
