    u_xlat15 = u_xlat15 * vs_TEXCOORD3.w;
    u_xlat15 = u_xlat15 * _f_buffer0.f_cb0[18].x;
    u_xlat0.xyz = vec3(u_xlat15) * u_xlat1.xyz + u_xlat0.xyz;
#ifdef UNITY_ADRENO_ES3
    u_xlat0.xyz = min(max(u_xlat0.xyz, 0.0), 1.0);
#else
    u_xlat0.xyz = clamp(u_xlat0.xyz, 0.0, 1.0);
#endif
    u_xlat1.xyz = u_xlat0.xyz + vec3(0.150000006, 0.150000006, 0.150000006);
    u_xlat1.xyz = u_xlat1.xyz * vs_COLOR0.xyz;
    u_xlat0.xyz = min(u_xlat0.xyz, u_xlat1.xyz);
    u_xlat1 = texture(f_t6TEX_with_SMPf_s1, vs_TEXCOORD1.xy);
    u_xlat0.w = 1.0;
    SV_Target0 = u_xlat0 * u_xlat1;
